const body = incoming.body ?? {};

let message = "";
if (typeof body === "string") {
  message = body;
} else if (body && typeof body === "object") {
  message = body.message ?? body.text ?? body.question ?? body.notes ?? body.content ?? "";
  if (!message) message = JSON.stringify(body);
} else {
  message = String(body ?? "");
}

message = String(message).trim().slice(0, 4000);
if (!message) throw new Error("No message provided. Send JSON with a \"message\" field.");

return [{ json: { message, original: body, query: incoming.query ?? {} } }];

