parameters.jsCode:
const ALLOWED = ["Upload Format","Captions and Discovery","AI Disclosure and Policy","Analytics and Growth"];
const src = $('Extract Message').first().json;
const ai = $input.first().json || {};

let out = ai.output ?? ai;
if (typeof out === "string") {
  try { out = JSON.parse(out); } catch {}
}
if (!out || typeof out !== "object") out = {};

const rawCategory = String(out.category ?? "").trim();
const canonical = ALLOWED.find((c) => c.toLowerCase() === rawCategory.toLowerCase()) || rawCategory;
const n = Number(out.confidence);
const confidence = Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0;
const reasoning = String(out.reasoning ?? out.reason ?? "").trim() || "No reasoning returned.";
const outOfScope = confidence < 0.2;

return [{
  json: {
    ok: true,
    message: src.message,
    classification: {
      category: canonical,
      confidence,
      reasoning,
    },
    category_valid: ALLOWED.includes(canonical),
    allowed_categories: ALLOWED,
    out_of_scope: outOfScope,
    original: src.original,
    query: src.query,
    at: new Date().toISOString(),
  },
}];

const cls = $('Validate Classification').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.entry_id);
const category = String(cls.classification.category || "").toLowerCase();
const message = String(cls.message || "").toLowerCase();
const tokens = new Set(message.split(/[^a-z0-9]+/).filter(Boolean));
const outOfScope = Boolean(cls.out_of_scope);

if (outOfScope) {
  return [{
    json: {
      message: cls.message,
      classification: cls.classification,
      category_valid: cls.category_valid,
      out_of_scope: true,
      matched: [],
      matched_count: 0,
    },
  }];
}

const scored = rows
  .map((r) => {
    const kw = String(r.keywords || "").toLowerCase();
    const platforms = String(r.platforms || "").toLowerCase();
    let score = 0;
    if (String(r.category || "").toLowerCase() === category) score += 2;
    for (const part of kw.split(",").map((s) => s.trim()).filter(Boolean)) {
      if (part && message.includes(part)) score += 3;
    }
    for (const t of tokens) {
      if (t.length > 2 && kw.includes(t)) score += 1;
      if (t.length > 2 && platforms.includes(t)) score += 1;
    }
    return { ...r, score };
  })
  .filter((r) => r.score > 0)
  .sort((a, b) => b.score - a.score || String(a.entry_id).localeCompare(String(b.entry_id)))
  .slice(0, 6);

return [{
  json: {
    message: cls.message,
    classification: cls.classification,
    category_valid: cls.category_valid,
    out_of_scope: false,
    matched: scored,
    matched_count: scored.length,
  },
}];

