const ai = $input.first().json || {};

let out = ai.output ?? ai;
if (typeof out === "string") {
  try { out = JSON.parse(out); } catch { out = { response: out }; }
}
if (!out || typeof out !== "object") out = {};

const response = String(out.response ?? out.answer ?? "").trim() || "No response was generated. Please try again.";
const nextSteps = Array.isArray(out.next_steps) ? out.next_steps.map((s) => String(s)).filter(Boolean) : [];
const escalation = String(out.escalation ?? "").trim();
const timestamp = new Date().toISOString();

return [{
  json: {
    ok: true,
    timestamp,
    message: src.message,
    classification: src.classification,
    category_valid: src.category_valid,
    matched_entries: src.matched.map((m) => ({
      entry_id: m.entry_id,
      question: m.question,
      score: m.score,
    })),
    matched_count: src.matched_count,
    out_of_scope: Boolean(src.out_of_scope || src.matched_count === 0),
    ai_response: response,
    next_steps: nextSteps,
    escalation,
    delivery_status: "webhook_200",
  },
}];

const r = $input.first().json;

return [{
  json: {
    timestamp: r.timestamp,
    message: r.message,
    category: r.classification.category,
